import{_ as t,o as p,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const a="/assets/image-cn2024.Zdn_cQVy.png",l="/assets/image-cn20241.RLeZCYMC.png",s="/assets/image-cn20242.Coe1o9Lo.png",n="/assets/image-cn20243.DL-1Agrr.png",d="/assets/image-cn20244.CDRlMu8n.png",i="/assets/image-20245.GD1nl7Hd.png",c="/assets/image-cn20246.BK4tTcaU.png",m="/assets/image-cn20247.2qxncxCl.png",b=JSON.parse('{"title":"Windows 服务器一键部署幻兽帕鲁","description":"","frontmatter":{"title":"Windows 服务器一键部署幻兽帕鲁"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/windows/deploy-palworld-one-click.md","filePath":"ops-knowledge-base/operating-system/windows/deploy-palworld-one-click.md","lastUpdated":1788259091000}'),g={name:"ops-knowledge-base/operating-system/windows/deploy-palworld-one-click.md"};function w(h,e,_,F,u,P){return p(),o("div",null,[...e[0]||(e[0]=[r('<p>部署环境</p><ul><li>服务器套餐配置：以CPU 4核、内存 16GB为例（通常可以满足6-8人同时在线联机）</li><li>操作系统：Windows Server 2019</li></ul><p>登录 Windows 服务器</p><p>1、登录raksmart控制台，获取服务器登录密码。如您忘记密码，可以在控制台重置密码：</p><p><img src="'+a+'" alt=""></p><p>2、使用电脑的“远程桌面连接”功能，输入IP地址、端口和账号，最后输入密码对服务器进行远程连接</p><p><img src="'+l+'" alt=""></p><p>部署</p><p>前置知识：PowerShell</p><p>Windows的一键部署需要借助 PowerShell 来完成。PowerShell是一种任务自动化和配置管理框架，它提供了一个命令行Shell和脚本语言，用于管理和控制Windows操作系统和相关应用程序。那么要如何找到 PowerShell ？方法如下：</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>方法</td><td>描述</td></tr><tr><td>使用开始菜单</td><td>点击Windows开始按钮，然后在搜索框中输入&quot;PowerShell&quot;。你应该能够看到&quot;Windows PowerShell&quot;或&quot;PowerShell&quot;的搜索结果。点击该结果即可打开PowerShell。</td></tr><tr><td>使用运行对话框</td><td>按下Win + R键组合，打开运行对话框。在对话框中输入&quot;powershell&quot;，然后点击&quot;确定&quot;按钮即可打开PowerShell。</td></tr><tr><td>使用文件资源管理器</td><td>打开文件资源管理器（Windows资源管理器），导航到所需的目录，然后在地址栏中输入&quot;powershell&quot;并按下回车键。这将在当前目录中打开PowerShell。</td></tr></tbody></table><p>第一步：下载 C++运行库（点击链接即可下载），需要手动安装。<a href="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Faka.ms%2Fvs%2F17%2Frelease%2Fvc_redist.x64.exe&amp;source=article&amp;objectId=2383611" title="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Faka.ms%2Fvs%2F17%2Frelease%2Fvc_redist.x64.exe&amp;source=article&amp;objectId=2383611" target="_blank" rel="noreferrer">https://aka.ms/vs/17/release/vc_redist.x64.exe</a></p><p>第二步：下载 DirectX 支持库（点击链接即可下载），需要手动安装。<a href="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Fwww.microsoft.com%2Fen-us%2Fdownload%2Fdetails.aspx%3Fid%3D35&amp;source=article&amp;objectId=2383611" title="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Fwww.microsoft.com%2Fen-us%2Fdownload%2Fdetails.aspx%3Fid%3D35&amp;source=article&amp;objectId=2383611" target="_blank" rel="noreferrer">https://www.microsoft.com/en-us/download/details.aspx?id=35</a></p><p>第三步：运行一键部署命令</p><p>一键部署的方式适用于想要快速上手幻兽帕鲁服务器的开发者，仅需运行一行命令即可完成部署。</p><p>我们参考官方教程，为您封装好了一键部署幻兽帕鲁的脚本，并且上传到云端，您仅需要登录服务器，复制并在 PowerShell 中运行如下命令，通常等待3-5分钟后，即可完成幻兽帕鲁的部署。</p><p>iex (irm &#39;<a href="https://pal.pet/pal-server/Windows/install.ps1" target="_blank" rel="noreferrer">https://pal.pet/pal-server/Windows/install.ps1</a>&#39;)</p><p>⚠️注意：如果您使用中国内地地域的服务器运行一键部署脚本，则有可能因为网络原因导致脚本运行失败，建议您多次重试或换个时间段再次部署。此处的原因主要是安装过程中需要请求Steam的服务器，网络连接状况可能不稳定。</p><p>第四步：关闭防火墙</p><p><img src="'+s+'" alt=""></p><p>⚠️注意：一定要关闭机器内的防火墙，否则服务器可能会连接不上</p><p>服务端启动与重启</p><p>服务端部署完成后，会自动启动。无需额外再次启动</p><p>服务器重启后，幻兽帕鲁服务端会自动启动</p><p>如果需要重启服务端，直接重启服务器即可</p><p>登录游戏</p><p>前置条件</p><ul><li>首先您需要在本地电脑中下载Steam客户端。</li><li>其次需要在Steam<a href="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Fstore.steampowered.com%2Fapp%2F1623730%2FPalworld%2F%3Fl%3Dschinese&amp;source=article&amp;objectId=2382000" title="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Fstore.steampowered.com%2Fapp%2F1623730%2FPalworld%2F%3Fl%3Dschinese&amp;source=article&amp;objectId=2382000" target="_blank" rel="noreferrer">购买幻兽帕鲁（Palworld）</a>。</li></ul><p>登录步骤</p><p>第一步：打开Steam客户端，并登录您的Steam账号。</p><p><img src="'+n+'" alt=""></p><p>第二步：在“库”中找到幻兽帕鲁，并点击【开始游戏】。</p><p><img src="'+d+'" alt=""></p><p>第三步：在游戏菜单选择【加入多人游戏（专用服务器）】。</p><p><img src="'+i+'" alt=""></p><p>第四步：至此，您已经成功搭建了幻兽帕鲁专属服务器（Dedicated Server），可以让玩家输入您已部署服务器的公网IP地址和端口好（如11.11.11.11:8211），连接服务器成功后即可畅快联机开玩。</p><p>⚠️注意：切记在公网IP与端口中间使用英文冒号，否则会提示<code>Format Error. Example: 127.0.0.1:7777</code>！！！</p><p><img src="'+c+'" alt=""></p><p>提示：您可以前往用户后台查看服务器的公网IP。在输入服务器的连接地址时，如您的服务器公网IP展示为：175.xxx.xx.138，则您需要在输入链接时填入：175.xxx.xx.138:8211</p><p>更新</p><p>打开PowerShell</p><p>输入一下命</p><p>iex (irm &#39;<a href="https://pal.pet/update%5C_windows.ps1" target="_blank" rel="noreferrer">https://pal.pet/update\\_windows.ps1</a>&#39;)</p><p>稍等片刻，等待任务执行成功即可完成更新。</p><p>手动配置游戏参数</p><p>幻兽帕鲁部署完成之后，如果您想要按照自己的喜好来对游戏世界进行 DIY，那么还需要进行如下步骤：</p><p>第一步：前往如下路径找到游戏世界参数的配置文件：<code>PalWorldSettings.ini</code></p><p>C:\\Program Files\\PalServer\\steam\\steamapps\\common\\PalServer\\Pal\\Saved\\Config\\WindowsServer\\PalWorldSettings.ini</p><p><img src="'+m+'" alt=""></p><p>第二步：选中该文件，右键单击，打开方式选择记事本。</p><p>第三步：按照您的需求写入具体的世界配置，以下内容仅作为示例，详细参数可查看<a href="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Ftech.palworldgame.com%2Foptimize-game-balance&amp;source=article&amp;objectId=2383611" title="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Ftech.palworldgame.com%2Foptimize-game-balance&amp;source=article&amp;objectId=2383611" target="_blank" rel="noreferrer">官方说明</a>。</p><p>Difficulty=None ServerName=Lighthouse ServerDescription=Lighthouse AdminPassword=ABC ServerPassword=TEST DeathPenalty=All bEnablePlayerToPlayerDamage=False</p><p>第四步：重启服务器后即可生效（您部署的幻兽帕鲁将会随之自启动）</p>',53)])])}const x=t(g,[["render",w]]);export{b as __pageData,x as default};
